:root {
  color-scheme: light;
  --page: #f9f9f7;
  --surface-1: #fcfcfb;
  --ink-1: #0b0b0b;
  --ink-2: #52514e;
  --ink-3: #898781;
  --grid: #e1e0d9;
  --baseline: #c3c2b7;
  --ring: rgba(11, 11, 11, 0.10);
  --series-1: #2a78d6;
  --series-2: #eb6834;
  --series-3: #1baf7a;
  --accent: #4a3aa7;         /* UI accent (anchor) — not a series slot in use */
  --lens-hi: #eda100;        /* lens highlight */
  --sel-bg: rgba(42, 120, 214, 0.08);
  --danger: #d03b3b;
  font-size: 13px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
[hidden] { display: none !important; } /* hidden 属性优先于任何 display 规则 */
html, body { height: 100%; }
body {
  font-family: system-ui, -apple-system, "Segoe UI", "Microsoft YaHei", sans-serif;
  background: var(--page);
  color: var(--ink-1);
  overflow: hidden;
}
#app { display: flex; flex-direction: column; height: 100vh; }

button { font: inherit; color: inherit; background: none; border: none; cursor: pointer; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; border-radius: 3px; }
.muted { color: var(--ink-3); }
b { font-weight: 600; }

