/* Lenscope · 多维透镜 — compact professional data tool
   Chrome/ink tokens per validated reference palette (light mode). */

:root {
  color-scheme: light;
  --page: #f9f9f7;
  --surface-1: #fcfcfb;
  --ink-1: #0b0b0b;
  --ink-2: #52514e;
  --ink-3: #898781;
  --grid: #e1e0d9;
  --baseline: #c3c2b7;
  --ring: rgba(11, 11, 11, 0.10);
  --series-1: #2a78d6;
  --series-2: #eb6834;
  --series-3: #1baf7a;
  --accent: #4a3aa7;         /* UI accent (anchor) — not a series slot in use */
  --lens-hi: #eda100;        /* lens highlight */
  --sel-bg: rgba(42, 120, 214, 0.08);
  --danger: #d03b3b;
  font-size: 13px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
[hidden] { display: none !important; } /* hidden 属性优先于任何 display 规则 */
html, body { height: 100%; }
body {
  font-family: system-ui, -apple-system, "Segoe UI", "Microsoft YaHei", sans-serif;
  background: var(--page);
  color: var(--ink-1);
  overflow: hidden;
}
#app { display: flex; flex-direction: column; height: 100vh; }

button { font: inherit; color: inherit; background: none; border: none; cursor: pointer; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; border-radius: 3px; }
.muted { color: var(--ink-3); }
b { font-weight: 600; }

/* ── header ─────────────────────────────────────────────────────────── */
.region-header {
  display: flex; align-items: center; gap: 16px;
  height: 44px; padding: 0 12px;
  background: var(--surface-1);
  border-bottom: 1px solid var(--ring);
  flex: none;
}
.brand { display: flex; align-items: center; gap: 8px; min-width: 0; }
.brand-mark {
  width: 14px; height: 14px; border-radius: 50%;
  border: 3px solid var(--accent); flex: none;
}
.brand-name { font-weight: 700; font-size: 13.5px; letter-spacing: .2px; }
.brand-sub { font-weight: 500; color: var(--ink-2); margin-left: 2px; }
.dataset-name { color: var(--ink-2); margin-left: 8px; white-space: nowrap; }
.live-counts { display: flex; gap: 14px; margin-left: auto; color: var(--ink-2); white-space: nowrap; }
.live-counts b { font-variant-numeric: tabular-nums; color: var(--ink-1); }
.count-sel b { color: var(--accent); }
.header-actions { display: flex; align-items: center; gap: 6px; }
.kbd-hint { color: var(--ink-3); font-size: 11.5px; margin-right: 4px; }

.btn {
  padding: 3px 10px; border: 1px solid var(--baseline); border-radius: 5px;
  background: var(--surface-1); font-size: 12px; color: var(--ink-1);
  white-space: nowrap;
}
.btn:hover:not(:disabled) { border-color: var(--ink-3); background: #f2f1ee; }
.btn:disabled { opacity: .4; cursor: default; }
.btn-ghost { border-color: transparent; color: var(--ink-2); }
.btn-primary { background: var(--accent); border-color: var(--accent); color: #fff; }
.btn-primary:hover:not(:disabled) { background: #3d2f8f; border-color: #3d2f8f; }

/* ── filter bar ─────────────────────────────────────────────────────── */
.region-filter-bar {
  display: flex; align-items: center; gap: 8px;
  min-height: 34px; padding: 3px 12px;
  background: var(--surface-1); border-bottom: 1px solid var(--ring);
  flex: none; flex-wrap: wrap;
}
.fb-label { color: var(--ink-3); font-size: 11.5px; letter-spacing: .5px; }
#region-filter-bar input[type="search"] {
  width: 200px; padding: 3px 8px;
  border: 1px solid var(--baseline); border-radius: 5px;
  font: inherit; font-size: 12px; background: var(--page);
}
#region-filter-bar input[type="search"]:focus { border-color: var(--accent); outline: none; }
.chip-tray { display: flex; gap: 5px; flex-wrap: wrap; flex: 1; min-height: 18px; }
.chip {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 2px 4px 2px 8px; font-size: 11.5px;
  background: var(--sel-bg); color: var(--ink-1);
  border: 1px solid rgba(42, 120, 214, .35); border-radius: 10px;
}
.chip .chip-x {
  width: 14px; height: 14px; line-height: 12px; text-align: center;
  border-radius: 50%; color: var(--ink-2); font-size: 11px;
}
.chip .chip-x:hover { background: rgba(11,11,11,.12); color: var(--ink-1); }
.chip b { font-weight: 600; }

/* ── main grid ──────────────────────────────────────────────────────── */
.main-grid {
  flex: 1; min-height: 0;
  display: grid; grid-template-columns: 236px minmax(0, 1fr) 296px;
}
.center-col { display: flex; flex-direction: column; min-width: 0; min-height: 0; }
.right-col {
  display: flex; flex-direction: column; min-height: 0;
  border-left: 1px solid var(--ring); background: var(--surface-1);
}

/* ── dim rail ───────────────────────────────────────────────────────── */
.region-rail {
  border-right: 1px solid var(--ring); background: var(--surface-1);
  display: flex; flex-direction: column; min-height: 0; overflow: hidden;
}
.rail-section { padding: 8px 0 4px; display: flex; flex-direction: column; min-height: 0; }
.rail-section-grow { flex: 1; overflow: hidden; }
.rail-head, .panel-head {
  padding: 2px 12px 6px; font-size: 11.5px; font-weight: 700;
  letter-spacing: .8px; color: var(--ink-2); text-transform: uppercase;
}
.rail-head-sub, .panel-head .rail-head-sub {
  font-weight: 400; letter-spacing: 0; text-transform: none; color: var(--ink-3); margin-left: 4px;
}
.trail {
  display: flex; flex-wrap: wrap; gap: 4px; padding: 0 12px 8px;
  border-bottom: 1px solid var(--grid); min-height: 24px;
}
.trail-chip {
  font-size: 11px; padding: 1px 8px; border-radius: 9px;
  background: var(--page); border: 1px solid var(--baseline); color: var(--ink-2);
}
.trail-chip:hover { border-color: var(--accent); color: var(--accent); }
.trail-empty { font-size: 11px; color: var(--ink-3); }

.dim-list { overflow-y: auto; flex: 1; padding-bottom: 8px; }
.dim-row { display: flex; align-items: stretch; border-left: 3px solid transparent; }
.dim-row.active { border-left-color: var(--lens-hi); background: #fdf6e7; }
.dim-row.active .dim-name { font-weight: 700; }
.dim-main {
  flex: 1; min-width: 0; display: flex; align-items: center; gap: 7px;
  padding: 4px 4px 4px 9px; text-align: left;
}
.dim-main:hover { background: #f2f1ee; }
.dim-type {
  flex: none; width: 17px; height: 15px; border-radius: 3px;
  font-size: 9.5px; font-weight: 700; line-height: 15px; text-align: center;
  color: var(--ink-2); background: var(--page); border: 1px solid var(--grid);
}
.dim-txt { min-width: 0; }
.dim-name { display: block; font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dim-unit { display: block; font-size: 10.5px; color: var(--ink-3); }
.dim-spark { flex: none; margin-left: auto; }
.lens-pill {
  flex: none; margin-right: 6px; font-size: 9.5px; font-weight: 700;
  color: #8a5b00; background: #fce8b8; border-radius: 3px; padding: 1px 5px;
}
.dim-toggle {
  flex: none; width: 22px; color: var(--ink-3); font-size: 10px;
  border-left: 1px solid var(--grid);
}
.dim-toggle:hover { color: var(--ink-1); background: #f2f1ee; }
.dim-filter {
  padding: 6px 10px 8px 19px; background: var(--page);
  border-bottom: 1px solid var(--grid); font-size: 12px;
}
.dim-filter .ck-row { display: flex; align-items: center; gap: 6px; padding: 1.5px 0; }
.dim-filter .ck-row label { flex: 1; cursor: pointer; }
.dim-filter .ck-count { color: var(--ink-3); font-variant-numeric: tabular-nums; }
.dim-filter .swatch { width: 9px; height: 9px; border-radius: 2px; flex: none; }
.range-row { display: flex; align-items: center; gap: 5px; }
.range-row input {
  width: 64px; padding: 2px 5px; font: inherit; font-size: 11.5px;
  border: 1px solid var(--baseline); border-radius: 4px; background: var(--surface-1);
}
.range-row .btn { padding: 2px 8px; font-size: 11px; }
.range-hint { color: var(--ink-3); font-size: 10.5px; margin-top: 3px; }

/* ── lens stage ─────────────────────────────────────────────────────── */
.region-stage {
  flex: none; height: 286px; display: flex; flex-direction: column;
  background: var(--surface-1); border-bottom: 1px solid var(--ring);
}
.stage-head {
  display: flex; align-items: center; gap: 10px; flex-wrap: wrap;
  padding: 6px 12px 4px;
}
.stage-title { display: flex; align-items: baseline; gap: 8px; min-width: 0; }
.lens-tag {
  flex: none; font-size: 10px; font-weight: 700; letter-spacing: 1px;
  color: #8a5b00; background: #fce8b8; border-radius: 3px; padding: 1.5px 6px;
  transform: translateY(-1px);
}
.stage-title h1 { font-size: 16px; font-weight: 700; }
.stage-stats { color: var(--ink-3); font-size: 11.5px; font-variant-numeric: tabular-nums; }
.stage-controls { margin-left: auto; display: flex; align-items: center; gap: 12px; }
.stage-controls label { font-size: 11.5px; color: var(--ink-2); display: flex; gap: 5px; align-items: center; }
.sel {
  font: inherit; font-size: 11.5px; padding: 2px 4px;
  border: 1px solid var(--baseline); border-radius: 4px; background: var(--surface-1);
}
.legend { display: flex; gap: 10px; }
.legend .lg { display: flex; align-items: center; gap: 4px; font-size: 11.5px; color: var(--ink-2); }
.legend .sw { width: 10px; height: 10px; border-radius: 2.5px; }
.stage-body { position: relative; flex: 1; min-height: 0; }
#chart { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.tooltip {
  position: fixed; z-index: 30; pointer-events: none;
  background: var(--surface-1); border: 1px solid var(--baseline); border-radius: 6px;
  box-shadow: 0 3px 12px rgba(11,11,11,.14);
  padding: 6px 9px; font-size: 11.5px; line-height: 1.5; max-width: 240px;
}
.tooltip .tt-name { font-weight: 700; }
.tooltip .tt-row { display: flex; justify-content: space-between; gap: 12px; color: var(--ink-2); }
.tooltip .tt-row b { font-variant-numeric: tabular-nums; color: var(--ink-1); font-weight: 600; }

/* ── record table ───────────────────────────────────────────────────── */
.region-table { flex: 1; min-height: 0; display: flex; flex-direction: column; background: var(--surface-1); }
.table-head-info {
  display: flex; justify-content: space-between; gap: 10px;
  padding: 5px 12px 4px; font-size: 11.5px; flex: none;
}
.table-scroll { flex: 1; overflow: auto; position: relative; }
.rtable { width: 100%; border-collapse: collapse; font-size: 12px; }
.rtable th {
  position: sticky; top: 0; z-index: 5;
  background: var(--page); color: var(--ink-2);
  font-size: 11px; font-weight: 600; text-align: right;
  padding: 4px 10px; border-bottom: 1px solid var(--baseline); border-top: 1px solid var(--grid);
  white-space: nowrap; cursor: pointer; user-select: none;
}
.rtable th:hover { color: var(--ink-1); }
.rtable th.th-lens { color: #8a5b00; box-shadow: inset 0 3px 0 var(--lens-hi); }
.rtable th.th-sorted::after { content: " ↓"; font-size: 10px; }
.rtable th.th-sorted-asc::after { content: " ↑"; font-size: 10px; }
.rtable th:first-child, .rtable td:first-child { text-align: center; width: 30px; }
.rtable th:nth-child(2), .rtable td:nth-child(2) { text-align: left; }
.rtable td {
  padding: 2.5px 10px; border-bottom: 1px solid var(--grid);
  text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap;
}
.rtable td.td-name { font-weight: 500; max-width: 150px; overflow: hidden; text-overflow: ellipsis; }
.rtable td .cellbar {
  display: inline-block; vertical-align: middle; height: 5px; border-radius: 2.5px;
  background: var(--series-1); opacity: .55; margin-right: 7px;
}
.rtable tr.row-sel td { background: var(--sel-bg); }
.rtable tr.row-sel td:first-child { box-shadow: inset 3px 0 0 var(--series-1); }
.rtable tr:hover td { background: #f2f1ee; }
.rtable tr.row-sel:hover td { background: rgba(42, 120, 214, 0.14); }
.anchor-btn { color: var(--baseline); font-size: 13px; line-height: 1; padding: 0 2px; }
.anchor-btn:hover { color: var(--accent); }
tr.row-anchor .anchor-btn { color: var(--accent); }
tr.row-anchor td:nth-child(2) .td-name::before {
  content: "◆ "; color: var(--accent); font-size: 10px; vertical-align: 1px;
}
.badge {
  display: inline-block; font-size: 10.5px; padding: 0 6px; border-radius: 8px;
  border: 1px solid var(--grid); color: var(--ink-2); background: var(--page);
  white-space: nowrap;
}
.insp-title .badge { align-self: flex-start; }
.table-empty {
  position: absolute; inset: 40px 0 0; display: flex; flex-direction: column;
  align-items: center; justify-content: center; gap: 8px; color: var(--ink-2);
}

/* ── inspector ──────────────────────────────────────────────────────── */
.region-inspector { flex: none; max-height: 46%; display: flex; flex-direction: column; border-bottom: 1px solid var(--ring); }
.inspector-body { overflow-y: auto; padding: 0 12px 10px; }
.insp-empty { color: var(--ink-3); font-size: 12px; padding: 8px 0 4px; }
.insp-title { display: flex; align-items: center; flex-wrap: wrap; gap: 4px 7px; margin-bottom: 6px; }
.insp-title h2 { font-size: 14.5px; }
.insp-actions { display: flex; gap: 5px; margin-left: auto; }
.insp-grid { width: 100%; border-collapse: collapse; font-size: 12px; }
.insp-grid td { padding: 2px 4px; border-bottom: 1px solid var(--grid); }
.insp-grid td:first-child { color: var(--ink-2); white-space: nowrap; width: 1%; }
.insp-grid td:last-child { text-align: right; font-variant-numeric: tabular-nums; width: 88px; }
.insp-grid tr.insp-lens td { background: #fdf6e7; font-weight: 600; }
.insp-grid tr.insp-lens td:first-child { box-shadow: inset 2px 0 0 var(--lens-hi); }
.insp-bar {
  display: block; height: 4px; border-radius: 2px; background: var(--series-1); opacity: .5;
  margin-top: 2px;
}
.insp-grid tr.insp-lens .insp-bar { opacity: .85; background: var(--lens-hi); }

/* ── journal ────────────────────────────────────────────────────────── */
.region-journal { flex: 1; min-height: 0; display: flex; flex-direction: column; }
.fold-note { padding: 0 12px 4px; font-size: 11px; color: var(--ink-3); }
.journal-list { flex: 1; overflow-y: auto; padding: 0 8px 10px; }
.j-entry {
  display: flex; align-items: center; gap: 7px; width: 100%; text-align: left;
  padding: 4px 6px; border: 1px solid transparent; border-radius: 6px;
}
.j-entry:hover { background: var(--page); border-color: var(--grid); }
.j-entry.current { background: var(--sel-bg); border-color: rgba(42,120,214,.35); }
.j-n {
  flex: none; width: 24px; height: 16px; border-radius: 4px;
  background: var(--page); border: 1px solid var(--grid);
  font-size: 10px; font-weight: 700; text-align: center; line-height: 15px; color: var(--ink-2);
}
.j-entry.current .j-n { background: var(--accent); border-color: var(--accent); color: #fff; }
.j-main { flex: 1; min-width: 0; }
.j-label { display: block; font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.j-sub { display: block; font-size: 10.5px; color: var(--ink-3); }
.j-restore { flex: none; font-size: 10.5px; color: var(--accent); padding: 1px 6px; border-radius: 4px; }
.j-restore:hover { background: rgba(74, 58, 167, .12); }
.j-undo-note { padding: 2px 12px 0; font-size: 10.5px; color: var(--ink-3); }

/* ── states ─────────────────────────────────────────────────────────── */
.loading {
  position: fixed; inset: 0; display: flex; align-items: center; justify-content: center;
  background: var(--page); z-index: 50; color: var(--ink-2);
}
.error-banner {
  position: fixed; left: 50%; bottom: 14px; transform: translateX(-50%);
  background: #fdecec; color: var(--danger); border: 1px solid var(--danger);
  border-radius: 8px; padding: 8px 14px; z-index: 60; font-size: 12.5px; max-width: 80vw;
}

/* scrollbars: recessive */
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-thumb { background: var(--grid); border-radius: 5px; border: 2px solid var(--surface-1); }
::-webkit-scrollbar-thumb:hover { background: var(--baseline); }

