  const pt = await evalJs(`(() => {
    const L = window.__lenscope;
    const r = L.plot.vis.find(r => r._x != null);
    const rect = document.getElementById('chart').getBoundingClientRect();
    return { x: rect.left + r._x, y: rect.top + r._y };
  })()`);
