      const p = pending.get(m.id);
      pending.delete(m.id);
      if (m.error) p.reject(new Error(m.error.message)); else p.resolve(m.result);
    } else if (m.method) {
      for (let i = eventWaiters.length - 1; i >= 0; i--) {
